-- golden: expressions/function_ord
-- django: 6.1
-- profile: 7.5
-- depends: ddl/create_author
-- params: [[]]
-- verified: IBM i 7.5 on PUB400 (TR unknown, Db2 PTF Group unknown), Django 6.1.3, 2026-11-13
SELECT CASE WHEN LENGTH("TESTAPP_AUTHOR"."NAME") = 0 THEN 0 WHEN INTERPRET(HEXTORAW('0000' CONCAT SUBSTR(HEX(CAST("TESTAPP_AUTHOR"."NAME" AS VARGRAPHIC(2) CCSID 1200)), 1, 4)) AS INTEGER) BETWEEN 55296 AND 56319 THEN (INTERPRET(HEXTORAW('0000' CONCAT SUBSTR(HEX(CAST("TESTAPP_AUTHOR"."NAME" AS VARGRAPHIC(2) CCSID 1200)), 1, 4)) AS INTEGER) - 55296) * 1024 + (INTERPRET(HEXTORAW('0000' CONCAT SUBSTR(HEX(CAST("TESTAPP_AUTHOR"."NAME" AS VARGRAPHIC(2) CCSID 1200)), 5, 4)) AS INTEGER) - 56320) + 65536 ELSE INTERPRET(HEXTORAW('0000' CONCAT SUBSTR(HEX(CAST("TESTAPP_AUTHOR"."NAME" AS VARGRAPHIC(2) CCSID 1200)), 1, 4)) AS INTEGER) END AS "X" FROM "TESTAPP_AUTHOR";
